function downloadText(mon,side){if(mon.dl)return {atk:'Atk',spa:'Sp. Atk',off:'None'}[mon.dl]||'Auto';const target=getMon(side==='mine'?'foe':'mine');if(!target)return 'Auto';const resolved=resolve(target);if(!resolved.stats)return 'Auto';const move=M.indexOf('Tackle'),event=move>=0?window.DMG.calc(toEngine(mon),toEngine(resolved),{mv:move},fieldFor(side))?.pre?.find(change=>change.who==='atk'&&change.src==='Download'):null;if(event)return 'Auto → '+(event.stat==='atk'?'Atk':'Sp. Atk');return 'Auto → '+(Math.floor(resolved.stats[2]*stageMul(resolved.stg[1]))<Math.floor(resolved.stats[4]*stageMul(resolved.stg[3]))?'Atk':'Sp. Atk');}
