 const sources=['weather','terrain'].map(kind=>ST.fman.includes(kind)?`${kind==='weather'?'Weather':'Terrain'} set by you (auto: ${AUTOFIELD[kind]||'none'})`:AUTOFIELD[kind]?`${AUTOFIELD[kind]}: ${FIELDSOURCES[kind]}`:'').filter(Boolean);
 const records=areaRecords(),effects=records.flatMap(record=>record.effects||[]),extra=[effects.some(effect=>effect.kind==='critical-bonus')?'+1 crit (foe, guess)':'',effects.some(effect=>effect.value==='Fog')?'Fog: accuracy ×0.6, no damage effect':''].filter(Boolean);
