function importMon(mon,ours,index){const tables=sourceData.GID||{},lookup=(kind,value)=>ours?value:tables[kind]?.[value];const id=lookup('sp',mon.sp);if(!byId[id])throw {code:'wrong',game:'Unmapped species '+mon.sp};const species=byId[id];const ability=mon.abs!=null?(mon.abs===2?species.ha:species.a[mon.abs]):lookup('ab',mon.ab);return {pid:encodeURIComponent(String(mon.pid??index)),id,l:Math.max(range[0],Math.min(range[1],Number(mon.lv)||range[0])),na:typeof mon.nat==='string'?mon.nat:natureOrder[mon.nat||0],a:Number.isInteger(ability)&&sourceData.AB[ability]?ability:species.a[0],i:lookup('it',mon.it)||'',m:(mon.mv||[]).slice(0,4).map(move=>{const mapped=lookup('mv',move);return Number.isInteger(mapped)&&MV[mapped]?mapped:null;}),iv:Array.from({length:6},(_,slot)=>Math.max(0,Math.min(31,Number(mon.iv?.[slot]??31)||0))),ev:Array.from({length:6},(_,slot)=>Math.max(0,Math.min(252,Number(mon.ev?.[slot])||0)))};}
async function importFile(file){try{const reader=window.READERS?.[prof.save];if(!reader)throw {code:'unreadable'};const result=reader(new Uint8Array(await file.arrayBuffer()),sourceData);if(!result.party?.length)throw {code:'empty'};const ours=result.ids==='ours';const party=result.party.map((mon,index)=>importMon(mon,ours,'p'+index));const boxes=(result.boxes||[]).map((box,boxIndex)=>box.map((mon,index)=>importMon(mon,ours,boxIndex+':'+index)));const keys=new Set([...Object.keys(ST.edits),...Object.keys(ST.saved)].filter(key=>key.startsWith('mine:')&&!ST.custom.some(mon=>key==='mine:'+mon.pid)));keys.forEach(key=>{delete ST.edits[key];delete ST.saved[key];});for(const container of [ST.crit,ST.hits,ST.mvo,ST.z,ST.st,ST.hitv])Object.keys(container).filter(key=>key.startsWith('mine:')&&!ST.custom.some(mon=>key.startsWith('mine:'+mon.pid+':'))).forEach(key=>delete container[key]);Object.keys(ST.tgt).filter(key=>key.startsWith('mine:')&&!ST.custom.some(mon=>key==='mine:'+mon.pid)).forEach(key=>delete ST.tgt[key]);ST.imp={file:file.name,at:Date.now(),party,boxes};if(ST.mine.src!=='custom')ST.mine={src:'party',b:0,i:0};BAN={ok:1,h:'Imported '+file.name,t:party.length+' in the party, '+boxes.reduce((count,box)=>count+box.length,0)+' in boxes'+(keys.size?' · '+keys.size+' edited Pokémon reset':'')};save();}catch(error){const messages={wrong:['Wrong game',error.game?String(error.game):'This save is for a different game or platform.'],state:['Save state','Pick the battery .sav file, not an emulator save state.'],unreadable:['Unreadable','Both save slots fail their checksum. Save again in-game.'],empty:['No Pokémon yet','This save has no party. Get your starter and save first.']};const message=messages[error.code]||messages.unreadable;BAN={ok:0,h:message[0],t:message[1]};}calcPage();}
input.onchange=async()=>{if(input.files[0])await importFile(input.files[0]);input.value='';};
